<?php
require_once __DIR__ . '/config/database.php';
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$productosCount=(int)$pdo->query('SELECT COUNT(*) FROM productos')->fetchColumn();
$equiposCount=(int)$pdo->query("SELECT COUNT(*) FROM productos WHERE tipo='Fotocopiadora' AND stock > 0")->fetchColumn();
$ventasMes=(int)$pdo->query('SELECT COUNT(*) FROM ventas WHERE YEAR(fecha)=YEAR(CURDATE()) AND MONTH(fecha)=MONTH(CURDATE())')->fetchColumn();
$servPend=(int)$pdo->query("SELECT COUNT(*) FROM servicios WHERE estado IN ('Pendiente','En revisión')")->fetchColumn();
$stockBajo=$pdo->query('SELECT nombre,ubicacion,stock,stock_minimo FROM productos WHERE stock <= stock_minimo ORDER BY stock ASC,nombre ASC LIMIT 8')->fetchAll();
$servRecientes=$pdo->query("SELECT codigo_servicio,cliente_nombre,equipo,estado FROM servicios WHERE estado <> 'Finalizado' ORDER BY fecha_ingreso ASC LIMIT 5")->fetchAll();
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>CONCE SUR | Panel de Control</title><link rel="stylesheet" href="css/style.css"><style>.dashboard-grid table{width:100%;border-collapse:collapse}.dashboard-grid th,.dashboard-grid td{text-align:left;padding:10px;border-bottom:1px solid #273449}.dashboard-grid th{color:#9ca3af;font-size:12px}.dashboard-grid td{font-size:13px}.empty{color:#9ca3af}.db-note{font-size:12px;color:#9ca3af;margin-top:12px}.service{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 0;border-bottom:1px solid #273449}.service strong{display:block}.service span{font-size:12px;color:#9ca3af}.pending{background:#78350f!important;color:#fde68a!important;padding:5px 8px;border-radius:6px;white-space:nowrap}.warning,.danger{font-size:12px;padding:4px 7px;border-radius:5px}.warning{background:#78350f;color:#fde68a}.danger{background:#7f1d1d;color:#fecaca}</style></head><body><div class="app"><aside class="sidebar"><div class="logo"><h1>CONCE SUR</h1><span>Sistema de Gestión</span></div><nav><a href="index.php" class="active">Dashboard</a><a href="pages/inventario.php">Inventario</a><a href="pages/ventas.php">Ventas</a><a href="#">Clientes</a><a href="pages/servicios.php">Servicios</a><a href="#">Equipos</a></nav><div class="sidebar-bottom"><a href="#">Configuración</a></div></aside><main class="main"><header class="topbar"><div><h2>Dashboard</h2><p>Resumen calculado desde la base de datos local</p></div><div class="user"><div class="avatar">A</div><div><strong>Administrador</strong><small>Prototipo local</small></div></div></header>
<section class="cards"><div class="card"><div class="card-icon">📦</div><div><span>Productos registrados</span><h3><?=number_format($productosCount)?></h3></div></div><div class="card"><div class="card-icon">🖨️</div><div><span>Modelos de fotocopiadora con stock</span><h3><?=number_format($equiposCount)?></h3></div></div><div class="card"><div class="card-icon">🧾</div><div><span>Ventas del mes</span><h3><?=number_format($ventasMes)?></h3></div></div><div class="card"><div class="card-icon">🔧</div><div><span>Servicios abiertos</span><h3><?=number_format($servPend)?></h3></div></div></section>
<section class="dashboard-grid"><div class="panel"><div class="panel-header"><div><h3>Stock bajo</h3><p>Productos que necesitan reposición</p></div><a href="pages/inventario.php">Ver inventario →</a></div><div style="overflow-x:auto"><table><thead><tr><th>Producto</th><th>Ubicación</th><th>Stock</th><th>Estado</th></tr></thead><tbody><?php if(!$stockBajo):?><tr><td colspan="4" class="empty">No hay productos por debajo de su mínimo configurado.</td></tr><?php else:foreach($stockBajo as $p):?><tr><td><?=h($p['nombre'])?></td><td><?=h($p['ubicacion'])?></td><td><?=number_format((int)$p['stock'])?></td><td><span class="<?=((int)$p['stock']===0?'danger':'warning')?>"><?=((int)$p['stock']===0?'Sin stock':'Stock bajo')?></span></td></tr><?php endforeach;endif;?></tbody></table></div></div>
<div class="panel"><div class="panel-header"><div><h3>Servicios pendientes</h3><p>Atenciones que aún no finalizaron</p></div><a href="pages/servicios.php">Ver servicios →</a></div><?php if(!$servRecientes):?><p class="empty">No hay servicios abiertos registrados.</p><?php else:foreach($servRecientes as $s):?><div class="service"><div><strong><?=h($s['equipo'])?></strong><span><?=h($s['codigo_servicio'] ?: 'Servicio')?> · <?=h($s['cliente_nombre'])?></span></div><span class="pending"><?=h($s['estado'])?></span></div><?php endforeach;endif;?></div></section><p class="db-note">Los indicadores y listas provienen de MySQL/MariaDB. Los registros DEMO del inventario son demostrativos y deben validarse o sustituirse por datos reales.</p></main></div></body></html>
